import fs from 'node:fs';import {createClient} from '@supabase/supabase-js';import {buildProductGroups} from '../src/features/panol/stockGrupos.js';process.loadEnvFile('.env');process.loadEnvFile('.env.backup.local');const db=createClient(process.env.VITE_SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});const schema=JSON.parse(fs.readFileSync('backups/placas-antiruido-20261103/schema.json'));const found={};const ts=['panol_materiales','panol_obra_materiales_snapshot','panol_envio_items','panol_comprobante_items','panol_obra_addons','panol_solicitud_items','purchase_request_items','linea_plantillas','panol_material_candidatos','panol_matriz_condicionante_items','pedido_items'];await Promise.all(ts.map(async t=>{const k=schema.definitions[t].properties.descripcion?'descripcion':'description';const r=await db.from(t).select('*').or(`${k}.ilike.%compos%,${k}.ilike.%ruido%`).order('id');if(r.error)throw r.error;found[t]=r.data;}));fs.writeFileSync('backups/placas-antiruido-20261103/referencias-antes.json',JSON.stringify(found,null,2));console.log(JSON.stringify(Object.fromEntries(Object.entries(found).map(([t,r])=>[t,{n:r.length,names:[...new Set(r.map(x=>x.descripcion||x.description))]}]))));const snaps=found.panol_obra_materiales_snapshot;console.log(JSON.stringify(buildProductGroups(snaps,'todas').map(g=>({label:g.label,total:g.total,libre:g.stockLibre,reservado:g.stockReservado,locations:g.locations?.map(l=>({obra:l.obraId,available:l.available}))}))));const r=await db.from('produccion_obras').select('id,codigo').in('id',[...new Set(snaps.map(x=>x.obra_id).filter(Boolean))]);console.log(JSON.stringify({obras:r.data}));fs.writeFileSync('backups/placas-antiruido-20261103/obras.json',JSON.stringify(r.data,null,2));
